package ai.learnharness.android;
import android.content.*;import android.view.*;import android.widget.*;import androidx.test.core.app.ActivityScenario;import androidx.test.platform.app.InstrumentationRegistry;import org.json.*;import org.junit.*;import java.util.*;import static org.junit.Assert.*;
public class SessionCreationDeviceTest {
 private android.content.Context context;private JSONObject before;private Map<String,?> preferences;
 @Before public void prepare()throws Exception{context=InstrumentationRegistry.getInstrumentation().getTargetContext();Records records=new Records(context);before=new JSONObject(records.root.toString());records.root=Records.empty();records.save();SharedPreferences prefs=context.getSharedPreferences("settings",0);preferences=new HashMap<>(prefs.getAll());prefs.edit().putBoolean("useChatGpt",false).putString("model","").putString("roleConnections","{}").putBoolean("eink",false).commit();}
 @After public void restore()throws Exception{Records records=new Records(context);records.root=before;records.save();SharedPreferences.Editor edit=context.getSharedPreferences("settings",0).edit().clear();for(var row:preferences.entrySet()){String key=row.getKey();Object value=row.getValue();if(value instanceof String)edit.putString(key,(String)value);else if(value instanceof Boolean)edit.putBoolean(key,(Boolean)value);else if(value instanceof Integer)edit.putInt(key,(Integer)value);else if(value instanceof Long)edit.putLong(key,(Long)value);else if(value instanceof Float)edit.putFloat(key,(Float)value);else if(value instanceof Set)edit.putStringSet(key,(Set<String>)value);}edit.commit();}
 private View text(View view,String label){if(view instanceof TextView && ((TextView)view).getText().toString().equals(label))return view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){View found=text(((ViewGroup)view).getChildAt(i),label);if(found!=null)return found;}return null;}
 private void click(View view){assertNotNull(view);while(!view.hasOnClickListeners() && view.getParent() instanceof View)view=(View)view.getParent();assertTrue(view.performClick());}
 private androidx.appcompat.app.AlertDialog dialog(MainActivity activity){try{var field=MainActivity.class.getDeclaredField("creationDialog");field.setAccessible(true);return (androidx.appcompat.app.AlertDialog)field.get(activity);}catch(Exception error){throw new AssertionError(error);}}
 private JSONObject record(MainActivity activity){try{var field=MainActivity.class.getDeclaredField("records");field.setAccessible(true);return ((Records)field.get(activity)).root;}catch(Exception error){throw new AssertionError(error);}}
 private <T extends View>T find(View root,Class<T> type){if(type.isInstance(root))return type.cast(root);if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){T found=find(((ViewGroup)root).getChildAt(i),type);if(found!=null)return found;}return null;}
 private View description(View root,String label){if(label.contentEquals(root.getContentDescription()==null?"":root.getContentDescription()))return root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){View found=description(((ViewGroup)root).getChildAt(i),label);if(found!=null)return found;}return null;}
 @Test public void newLessonOpensChatAndFirstMessageDefinesGoalWithoutModal()throws Exception{
  try(ActivityScenario<MainActivity> scene=ActivityScenario.launch(MainActivity.class)){scene.onActivity(a->{click(text(a.getWindow().getDecorView(),"New learning session"));assertNull(dialog(a));View root=a.getWindow().getDecorView();assertNotNull(text(root,"What do you want to learn?"));assertNull(text(root,"Start lesson"));assertNull(text(root,"Ready to begin"));assertEquals(0,record(a).optJSONArray("sessions").optJSONObject(0).optJSONArray("messages").length());click(description(root,"Send reply"));assertNotNull(find(a.getWindow().getDecorView(),com.google.android.material.textfield.TextInputEditText.class).getError());find(a.getWindow().getDecorView(),com.google.android.material.textfield.TextInputEditText.class).setText("How groundwater, rivers, and human water use fit together");click(description(a.getWindow().getDecorView(),"Send reply"));JSONObject saved=record(a).optJSONArray("sessions").optJSONObject(0);assertEquals(1,saved.optJSONArray("messages").length());assertEquals("How groundwater, rivers, and human water use fit together",saved.optJSONArray("messages").optJSONObject(0).optString("content"));assertEquals(saved.optJSONArray("messages").optJSONObject(0).optString("content"),saved.optString("title"));assertNotNull(text(a.getWindow().getDecorView(),"Set up AI connection"));assertNull(text(a.getWindow().getDecorView(),"Start lesson"));assertNull(text(a.getWindow().getDecorView(),"What do you want to learn?"));a.getOnBackPressedDispatcher().onBackPressed();assertNotNull(text(a.getWindow().getDecorView(),saved.optString("title")));});assertEquals(1,new Records(context).rows("sessions").getJSONObject(0).getJSONArray("messages").length());}
 }
 @Test public void newChatDraftSurvivesActivityRecreationWithoutCreatingAUserTurn()throws Exception{
  try(ActivityScenario<MainActivity> scene=ActivityScenario.launch(MainActivity.class)){scene.onActivity(a->{click(text(a.getWindow().getDecorView(),"New learning session"));find(a.getWindow().getDecorView(),com.google.android.material.textfield.TextInputEditText.class).setText("Keep this unfinished goal");});scene.recreate();InstrumentationRegistry.getInstrumentation().waitForIdleSync();scene.onActivity(a->{assertNull(dialog(a));assertEquals("Keep this unfinished goal",find(a.getWindow().getDecorView(),com.google.android.material.textfield.TextInputEditText.class).getText().toString());assertEquals(0,record(a).optJSONArray("sessions").optJSONObject(0).optJSONArray("messages").length());assertNotNull(text(a.getWindow().getDecorView(),"What do you want to learn?"));});}
 }
 @Test public void pendingScopeQuestionOffersSubmitInsteadOfASecondStart()throws Exception{
  JSONObject call=ToolProtocol.call("water_scope","ask_user_question","{}"),question=new JSONObject().put("id","water_scope").put("kind","ask").put("tool","ask_user_question").put("question","Which part of the water cycle would you like to understand?").put("mode","single-select").put("options",new JSONArray().put(new JSONObject().put("label","Groundwater, rivers, and human water use").put("value","groundwater"))).put("call",call);
  Records records=new Records(context);String id=Records.id();records.rows("sessions").put(new JSONObject().put("id",id).put("title","Water cycle").put("phase","Explore").put("messages",new JSONArray().put(new JSONObject().put("role","user").put("content","Water cycle"))).put("pendingQuestion",question).put("agentHistory",new JSONArray().put(new JSONObject().put("role","user").put("content","Water cycle")).put(new JSONObject().put("role","assistant").put("content","").put("tool_calls",new JSONArray().put(call)))));records.save();
  try(ActivityScenario<MainActivity> scene=ActivityScenario.launch(MainActivity.class)){scene.onActivity(a->{click(text(a.getWindow().getDecorView(),"Water cycle"));View root=a.getWindow().getDecorView();assertNull(text(root,"Start lesson"));assertNull(text(root,"Ready to begin"));assertNotNull(text(root,"Submit answer"));((CompoundButton)text(root,"Groundwater, rivers, and human water use")).performClick();click(text(root,"Submit answer"));});JSONObject saved=null;for(int i=0;i<70;i++){saved=new Records(context).find("sessions",id);if(!saved.has("pendingQuestion"))break;Thread.sleep(100);}assertNotNull(saved);assertFalse(saved.has("pendingQuestion"));assertEquals("tool",saved.getJSONArray("agentHistory").getJSONObject(2).getString("role"));assertTrue(saved.getJSONArray("agentHistory").getJSONObject(2).getString("content").contains("Groundwater"));}
 }
 @Test public void practiceUsesSameValidationAndCreatesVisibleSavedSession(){
  try(ActivityScenario<MainActivity> scene=ActivityScenario.launch(MainActivity.class)){scene.onActivity(a->{((com.google.android.material.bottomnavigation.BottomNavigationView)a.findViewById(R.id.bottom_navigation)).setSelectedItemId(R.id.nav_practice);click(text(a.getWindow().getDecorView(),"New practice session"));var popup=dialog(a);popup.getButton(-1).performClick();assertTrue(popup.isShowing());assertNotNull(((com.google.android.material.textfield.TextInputLayout)popup.findViewById(R.id.creation_goal_layout)).getError());((EditText)popup.findViewById(R.id.creation_goal)).setText("Practice QA fractions");popup.getButton(-1).performClick();assertNull(dialog(a));assertNotNull("Created practice should show setup state",text(a.getWindow().getDecorView(),"Set up AI connection"));assertEquals("practice",record(a).optJSONArray("sessions").optJSONObject(0).optString("kind"));a.getOnBackPressedDispatcher().onBackPressed();assertNotNull(text(a.getWindow().getDecorView(),"Practice QA fractions"));});}
 }
}
